var easeInElastic = function (t) { return (.04 - .04 / t) * Math.sin(25 * t) + 1 };
var ballCount = 30;
var balls = [];

function setup() {
	createCanvas(600, 600);
	noStroke();
	fill(255);
	for (i = 0; i < ballCount; i++) {
		balls[i] = new Ball();
	}
}

function draw() {
	blendMode(BLEND);
	background(255);
	blendMode(DIFFERENCE);
	balls.forEach(bl => bl.updateMe());
	balls.forEach(bl => bl.drawMe());
}

class Ball {
	constructor() {
		this.x = random(50, width - 50);
		this.y = random(50, height - 50);
		this.minR = random(10, 50);
		this.maxR = random(100, width);
		this.vec = getBool(.5);
		this.vec ? this.r = this.minR:this.r = this.maxR;
		this.easeTime = random(500, 2000);
		this.isChange = false;
		this.morphTime = millis();
	}

	updateMe() {
		if (this.isChange) {
			let t = (millis() - this.morphTime) / this.easeTime;
			if (millis() - this.morphTime < this.easeTime) {
			this.vec ? this.r = this.minR + (easeInElastic(t) * (this.maxR - this.minR))
				:this.r = this.maxR - (easeInElastic(t) * (this.maxR - this.minR));
			} else {
				this.isChange = false;
				this.vec ? this.r = this.maxR:this.r = this.minR;
				this.vec = !this.vec;
			}
		} else {
			if (random() < .0002) {
				this.morphTime = millis();
				this.isChange = true;
			}
		}
	}

	drawMe() {
		ellipse(this.x, this.y, this.r);
	}

	mouseClicked() {
		if (dist(this.x, this.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) < this.r / 2 && this.isChange == false) {
			this.morphTime = millis();
			this.isChange = true;
		}
	}
}

function getBool(p) {
	return random() > p ? true: false;
}

function mouseClicked() {
	balls.forEach(bl => bl.mouseClicked());
}
